/**
 * The sentence under the filename row when a save does more than write the
 * file in place. This default is for a save that moves the file: one file the
 * whole time, and nothing archived. An app whose save does something else
 * passes its own `describeSave`.
 */
export function describeMoveSave(s) {
  if (s.willRename && s.willMove)
    return `Save moves and renames "${s.origin}" to "${s.destination}"`
  if (s.willRename) return `Save renames "${s.origin}" to "${s.destination}"`
  if (s.willMove) {
    return `Save moves "${s.initialFileName}" to ${s.folder ? `"${s.folder}"` : 'the top level'}`
  }
  if (s.recyclePending) {
    return `Computed name: "${s.computedFileName}". Click ↺ to apply it, which renames the file`
  }
  return undefined
}

